using System;

public static class SpanishQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://es.wikiquote.org/wiki/Thelma_Fardin", Text = "Hasta hace poco tiempo yo pensaba que era responsabilidad mía. Ahora que soy una mujer me doy cuenta que era una criatura. Los adultos deben ser los que deben preservar a las menores.", Author = "Thelma Fardin" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carbono", Text = "La Química disuelve a la diosa en el alambique,", Author = "Carbono" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Miguel_Carrera", Text = "Este viejo demente ni era patriota ni sarraceno, y por sí nada podía hacer.", Author = "José Miguel Carrera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Giuseppe_Lanza_del_Vasto", Text = "Encuentra el camino más corto y sencillo entre la tierra, las manos y la boca.", Author = "Giuseppe Lanza del Vasto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tsung-Dao_Lee", Text = "El progreso de la ciencia siempre ha sido el resultado de una estrecha interacción entre nuestros conceptos del universo y nuestras observaciones sobre la naturaleza.", Author = "Tsung-Dao Lee" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ram%C3%B3n_de_Mesonero_Romanos", Text = "El aire de [la] corte es semejante al tufo en una pieza cerrada, que sólo le perciben los que vienen de fuera.", Author = "Ramón de Mesonero Romanos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Charlas_de_caf%C3%A9", Text = "Hay pocos lazos de amistad tan fuertes que no puedan ser cortados por un cabello de mujer.", Author = "Charlas de café" },
        new Quote { Id = "https://es.wikiquote.org/wiki/La_caja_negra_de_Darwin", Text = "Al ir en aumento el número de sistemas biológicos de complejidad irreducible que carecen de explicación, nuestra confianza en que se ha satisfecho el criterio darwiniano de fracaso se dispara hasta las más altas cotas que permite la ciencia.", Author = "La caja negra de Darwin" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_Arrate", Text = "Murió, pero aún respira.", Author = "Jorge Arrate" },
        new Quote { Id = "https://es.wikiquote.org/wiki/David_Trueba", Text = "Quiero tranquilizaros: he pasado el índice de masa corporal. Por lo tanto, puedo actuar esta noche tranquilo, y después cenar incluso.", Author = "David Trueba" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vanina_Biasi", Text = "Al aborto y la ESI lo defendemos en las calles contra los gobiernos ajustadores y la derecha reaccionaria.", Author = "Vanina Biasi" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Doctor", Text = "Este tal doctor dice él mismo de sí mismo que él no cura las enfermedades cuando las hay, sino que las previene, para que no vengan; y las medecinas que usa son dieta y más dieta, hasta poner la persona en los huesos mondos, como si no fuese mayor mal la flaqueza que la calentura.", Author = "Doctor" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hermano", Text = "Un hermano puede no ser un amigo pero un amigo será siempre un hermano.", Author = "Hermano" },
        new Quote { Id = "https://es.wikiquote.org/wiki/John_Muir", Text = "Cuando uno tira de una sola cosa en la naturaleza, la encuentra unida al resto del mundo.", Author = "John Muir" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Justus_von_Liebig", Text = "El progreso de la humanidad se debe exclusivamente a los avances de las ciencias naturales, no a la moral, la religión o la filosofía.", Author = "Justus von Liebig" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Dentro_y_fuera", Text = "Ser educado quiere decir ser, por dentro, negro como el cuervo, y por fuera, blanco como una paloma. En el cuerpo, hiel. En los labios, miel.", Author = "Dentro y fuera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rosa_Butler_y_Mendieta", Text = "Desgracias y pesadumbres la hicieron abandonar las letras hace muchos años.", Author = "Rosa Butler y Mendieta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mario", Text = "Con el ruido de la guerra no oigo el de las leyes.", Author = "Mario" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Warren_Zevon", Text = "Dormiré cuando esté muerto.", Author = "Warren Zevon" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ellen_Johnson-Sirleaf", Text = "El tamaño de tus sueños siempre debe exceder su capacidad actual para lograrlos. Si tus sueños no te asustan, no son lo suficientemente grandes.", Author = "Ellen Johnson-Sirleaf" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Marilyn_Manson", Text = "A los padres y legisladores les encanta echarles la culpa a gente como nosotros por corromper la juventud de este país, pero los chavales estaban corruptos mucho antes de que nosotros llegáramos a ellos.", Author = "Marilyn Manson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vanidad", Text = "La vanidad nos persigue hasta en el lecho de la muerte. La soportamos con entereza porque deseamos superar su terrible grandeza y cautivar la admiración de los espectadores.", Author = "Vanidad" },
        new Quote { Id = "https://es.wikiquote.org/wiki/J._G._Ballard", Text = "Todo se está convirtiendo en ciencia ficción. De los márgenes de una literatura casi invisible ha brotado la realidad entera del siglo XX.", Author = "J. G. Ballard" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Roberto_de_Mesquita", Text = "Alma mía, ¿de dónde viene el dolor que te invade? / ¿Qué Edén te sientes perdido? / ¡Oh! ¡Este es un poderoso lleno de añoranza / Sin objetivo definido!.", Author = "Roberto de Mesquita" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Brad_Pitt", Text = "Me gusta hacer todo tipo de películas, interpretaciones frescas. A mi edad [58] has cometido suficientes errores. Y con suerte has acumulado suficiente experiencia de lo que hiciste bien, de lo que hiciste mal. Y ahora tienes que ser capaz de aplicar esa especie de sabiduría.", Author = "Brad Pitt" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Seis", Text = "El rico tiene cinco sentidos y el pobre seis. [18] proverbios suecos", Author = "Seis" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lejos", Text = "Quien pisa con suavidad va lejos.[23] proverbios chinos", Author = "Lejos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lanza", Text = "Se puede parar un golpe de lanza, pero no un golpe de lengua.[11] proverbios malayos", Author = "Lanza" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Buen_gusto", Text = "El buen gusto es mejor que el mal gusto, pero el mal gusto es mejor que no tener gusto, y los nombres sin individualidad no tienen gusto —al menos no un gusto que pueden imponer sobre sus públicos—.", Author = "Buen gusto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_en_espa%C3%B1ol_%28B%29", Text = "Barriga caliente, pie durmiente.", Author = "Refranes en español (B)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pasi%C3%B3n_Vega", Text = "Quiero buscar caminos para interpretar y expresar; no quiero cantar cualquier cosa.", Author = "Pasión Vega" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Nacho_Vidal", Text = "El porno es para la masturbación. Y punto.", Author = "Nacho Vidal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Profeta", Text = "Nadie es profeta en su tierra.", Author = "Profeta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sentencia", Text = "Guarde para su regaloesta sentencia el autor:si el sabio no aprueba, ¡malo!si el necio aplaude, ¡peor!", Author = "Sentencia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Henry_Miller", Text = "Vivir creativamente significa —⁠como he descubierto⁠— hacerlo cada vez más desinteresadamente, cada vez más dentro del mundo, identificándote con él y, por tanto, influyéndolo en su corazón, por decirlo así. El arte, como la religión, es sólo una forma de prepararse, iniciase en el arte de vivir.", Author = "Henry Miller" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lidia_Sogandares", Text = "Desde que tengo conciencia, abrigaba el ansia de ser médica. Ese deseo mío era algo insólito. Todos me decían que no lograría nunca mi anhelo y que pronto me aburriría.", Author = "Lidia Sogandares" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hugo_Ch%C3%A1vez", Text = "Claro que la historia se enlaza, como tu vas a romper las cadenas de la historia, imposible que las rompas.", Author = "Hugo Chávez" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Victoria_Kent", Text = "Lo humano, que es tan grande como el universo y tan pequeño como sus componentes.", Author = "Victoria Kent" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Manuel_Sol%C3%ADs_Palma", Text = "El comandante ordena, el presidente obedece.", Author = "Manuel Solís Palma" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Enemistad", Text = "No es en los banquetes, sino en las cárceles, donde se puede saber si un enemigo es un buen amigo.[35] proverbios serbios", Author = "Enemistad" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cuerpo_y_alma", Text = "El cuerpo se mantiene por los alimentos y el alma por las buenas acciones.[36] proverbio chino", Author = "Cuerpo y alma" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carolina_Herrera", Text = "Las faldas son preciosas.. Se mueven muy bien y son muy femeninas. Ellas hacen que las mujeres se vean realmente como mujeres.", Author = "Carolina Herrera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vita_Sackville-West", Text = "Los felinos mayores con ojos doradosObservan desde detrás de los barrotes.Hay desiertos ahí, y cielos distintos,Y la noche con distintas estrellas.", Author = "Vita Sackville-West" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Canad%C3%A1", Text = "Estoy orgullosa de ser la primera miembro de la familia real canadiense en ser bienvenida al más nuevo territorio de Cánadá.", Author = "Canadá" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tim%C3%A1genes", Text = "Por lo único que me duelen los incendios de la ciudad es porque sé que las ruinas serán reedificadas mejor que antes de ser quemadas.", Author = "Timágenes" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rana", Text = "La luna va por el agua.¡Cómo está el cielo tranquilo!Va segando lentamenteel temblor viejo del ríomientras que una rana jóvenla toma por espejito.", Author = "Rana" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Toro_Sentado", Text = "¡Indios! ¡No hay más indios excepto yo!.", Author = "Toro Sentado" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Meryl_Streep", Text = "Cuando nacemos nos identificamos con los demás, sentimos empatía. Los bebés lloran solo con ver las lágrimas de otro, pero a medida que crecemos reprimimos esos sentimientos para suplantarlos a favor de una ideología o como un escudo. Y así llegamos a este triste momento de la Historia.", Author = "Meryl Streep" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Libro_de_los_ejemplos", Text = "A todo espíritu no es de creer / ni ligeramente obedecer.", Author = "Libro de los ejemplos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ang%C3%A9lica_Motta", Text = "A todo lo masculino se le da más valor y tiene una connotación de superioridad; mientras que a lo femenino se le connota inferioridad. El sistema machista busca mantener esa relación jerárquica. Para mantener estos estereotipos que ponen a las mujeres en ese lugar subordinado, utilizan la violencia.", Author = "Angélica Motta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Del_arte_de_la_guerra", Text = "¿En cuál hombre debe buscar la patria mayor fe sino en aquel que ha jurado dar su vida por ella? ¿Qué hombre debe anhelar más la paz sino aquel que de la guerra puede recibir mayor perjuicio?", Author = "Del arte de la guerra" },
        new Quote { Id = "https://es.wikiquote.org/wiki/R%C3%B3mulo_Escobar_Bethancourt", Text = "La Revolución panameña, señores, no transita por una carretera. Estamos abriendo una trocha y algún día esta trocha será una avenida ancha que conduzca al bienestar y felicidad del panameño.", Author = "Rómulo Escobar Bethancourt" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Patxi_L%C3%B3pez", Text = "Pues va a ser que no.", Author = "Patxi López" },
        new Quote { Id = "https://es.wikiquote.org/wiki/John_W._Tukey", Text = "La combinación de algunos datos y el compungido deseo de una respuesta no garantiza que se pueda extraer una respuesta razonable de un cuerpo de datos determinado.", Author = "John W. Tukey" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cine_africano", Text = "¿Por qué África nos importa tanto? ¿Por qué vamos a ver películas africanas? Justamente porque en un mundo que se encierra sobre sí mismo y refuerza las fronteras, las expresiones culturales abren las puertas a una humanidad unida en su diversidad.", Author = "Cine africano" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pedro_Mar%C3%ADa_Anaya", Text = "Si tuviéramos parque, no estarían ustedes aquí.", Author = "Pedro María Anaya" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Fernanda_Reyes", Text = "En el centro de la política no debe estar la corporación económica, ni la mediática, ni tampoco la corporación política. Deben estar los intereses de la ciudadanía.", Author = "Fernanda Reyes" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Fernando_Tejero", Text = "Un poquito de por favor.", Author = "Fernando Tejero" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Futuro", Text = "Me interesa el futuro porque en él voy a pasar el resto de mi vida.", Author = "Futuro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pasado", Text = "No hay originalidad posible sin un poco de rebeldía contra el pasado.", Author = "Pasado" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Septiembre", Text = "Finaliza septiembre. Es hora de decirtelo difícil que ha sido no morir.", Author = "Septiembre" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Serge_Latouche", Text = "El decrecimiento, al igual que promueve el reciclaje de desechos materiales, también debe interesarse por la rehabilitación de los excluídos. Y si el mejor reciclaje consiste en desechar menos, la mejor forma de rehabilitación social consiste en evitar la exclusión.", Author = "Serge Latouche" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Larry_Niven", Text = "Hay gente que cree que odia los ordenadores. Lo que odian en realidad son los malos programadores.", Author = "Larry Niven" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alicia_en_el_pa%C3%ADs_de_las_maravillas", Text = "La Reina de Corazones hizo unas tartas,", Author = "Alicia en el país de las maravillas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jeannette_Miller", Text = "Clasismo, naturalismo, costumbrismo e impresionismo, han sido los lenguajes mayormente utilizados en la pintura de paisajes, retratos, bodegones frutales y florales.", Author = "Jeannette Miller" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Malwida_von_Meysenbug", Text = "Memorias de una idealista (1900). Ediciones en alemán.", Author = "Malwida von Meysenbug" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Saltar", Text = "El hombre no puede saltar fuera de su sombra.[12] proverbios árabes", Author = "Saltar" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Secta", Text = "Cada verdad tiene su secta. Y cada secta tiene su verdad.[13] proverbios chinos", Author = "Secta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Theodore_Sturgeon", Text = "Básicamente, la ficción es gente. No puedes escribir ficción sobre ideas.", Author = "Theodore Sturgeon" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Neil_deGrasse_Tyson", Text = "Es curioso que dediquemos más tiempo a felicitar a las personas que han tenido éxito que a alentar a las que no lo han hecho.", Author = "Neil deGrasse Tyson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jean-Baptiste_Lamarck", Text = "A Lamarck corresponde la imperecedera gloria de haber sido el primero en elevar la teoría de la descendencia a la altura de una teoría científica independiente y de haber hecho de la filosofía de la Naturaleza la base sólida de toda la biología.", Author = "Jean-Baptiste Lamarck" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Henri_Poincar%C3%A9", Text = "Así, el espacio absoluto, el tiempo absoluto, la geometría misma no son condiciones impuestas a la mecánica; todas estas cosas no preexisten a la mecánica, como tampoco la lengua francesa preexiste lógicamente a las verdades expresadas en francés.", Author = "Henri Poincaré" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Soledades._Galer%C3%ADas._Otros_poemas", Text = "He andado muchos caminos,he abierto muchas veredas,he navegado en cien mares,y atracado en cien riberas.", Author = "Soledades. Galerías. Otros poemas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/J._Edgar_Hoover", Text = "Los miles de criminales que he visto en 40 años de aplicación de la ley, han tenido una cosa en común: Todos y cada uno de ellos era un mentiroso.", Author = "J. Edgar Hoover" },
        new Quote { Id = "https://es.wikiquote.org/wiki/James_Gilligan", Text = "Las hambrunas, al menos durante el último siglo de nuestra historia no han sido causadas por la falta de alimento. Han sido causadas por la relativa pobreza.", Author = "James Gilligan" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cartas_a_Lucilio", Text = "A muchos gobernarás si la razón te gobierna a ti. Carta XXXVII", Author = "Cartas a Lucilio" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Apaga_y_v%C3%A1monos", Text = "Vino Federico II, se extendió su espíritu maligno y apaga y vámonos.", Author = "Apaga y vámonos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pete_Doherty", Text = "El último momento exultante que he vivido fue esta mañana, caminando a orillas del Sena. Quise gastarle una broma a un pescador. Le dije que no le iban a picar, pero no debió entenderme.", Author = "Pete Doherty" },
        new Quote { Id = "https://es.wikiquote.org/wiki/%C3%81ngel_Crespo", Text = "En el país de los tuertos, el ciego es el rey.", Author = "Ángel Crespo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Estefan%C3%ADa_Banini", Text = "Cuando un grupo está completamente unido y con un objetivo en común, puede lograr cualquier cosa.", Author = "Estefanía Banini" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Eva_Joly", Text = "La corrupción es un problema universal. Lo que vemos no es un fenómeno singular, no es una curiosidad, no son los individuos que han perdido su dirección. Parece un sistema.", Author = "Eva Joly" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jerez_de_la_Frontera", Text = "La Muy Noble y Muy Leal Ciudad de Jerez de la Frontera", Author = "Jerez de la Frontera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bicicleta", Text = "A las dictaduras les pasa lo que a las bicicletas; si se paran, se caen.", Author = "Bicicleta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sexto_sentido", Text = "La pobreza es el sexto sentido.[5] proverbios alemanes", Author = "Sexto sentido" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cielos_velazque%C3%B1os", Text = "Cielos velazqueños se llaman por antonomasia los profundos y de claras tonalidades, característicos de la meseta.", Author = "Cielos velazqueños" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Eduardo_Chillida", Text = "Cuando conocí la tierra con la que yo quería trabajar, le puse la mano encima y enseguida me di cuenta por el oído, que me decía que era posible hacer mi obra con ella.", Author = "Eduardo Chillida" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cristina_Lobaiza_Estrada", Text = "Una mujer que dice de sí misma que está sola no necesita explicarle a nadie de qué está hablando: la soledad de una mujer siempre es soledad de hombre.", Author = "Cristina Lobaiza Estrada" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_uruguayos", Text = "Caliente como china en baile.", Author = "Refranes uruguayos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/John_William_Cooke", Text = "Cuando culmine el proceso revolucionario argentino, se iluminará el aporte de cada episodio y ningún esfuerzo será en vano, ningún sacrificio estéril, y el éxito final redimirá de todas las frustraciones.", Author = "John William Cooke" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Citas_incorrectas", Text = "Ladran, Sancho, señal de que cabalgamos.", Author = "Citas incorrectas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tiran%C3%ADa", Text = "Cuando en la misma persona o en el mismo cuerpo de magistratura, la potestad legislativa y la potestad ejecutiva están reunidas, no puede haber libertad; porque se puede temer que el mismo monarca o senado pueda hacer leyes tiránicas, para ejecutarlas tiránicamente.", Author = "Tiranía" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Calvo_Sotelo", Text = "Los términos son claros: Dios o ateísmo, autoridad o anarquía y comunismo. En España hay derechas e izquierdas; centro no.", Author = "José Calvo Sotelo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Steven_Gerrard", Text = "¿Cómo puedo pensar en dejar Liverpool después de una noche como ésta?", Author = "Steven Gerrard" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Enrique_Rod%C3%B3", Text = "Querer la paz por incapacidad para la guerra; querer la paz por el sentimiento de la propia debilidad, por el temor de la superioridad ajena, es condición miserable de los pueblos que no tienen en sí mismos la garantía suprema de su persistencia y de su dignidad.", Author = "José Enrique Rodó" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Nora_Corti%C3%B1as", Text = "A nuestros hijos desaparecidos los extrañamos todos los días, nos faltan los 30 mil pero están acá, en cada uno y una de ustedes.", Author = "Nora Cortiñas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Theodor_Adorno", Text = "En virtud de la ideología de la industria cultural, el conformismo sustituye a la autonomía y a la conciencia; jamas el orden que surge de esto es confrontado con lo que pretende ser, o con los intereses reales de los hombres.", Author = "Theodor Adorno" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pastor", Text = "Los pastores serán brutales mientras las ovejas sean estúpidas.[13] proverbios turcos", Author = "Pastor" },
        new Quote { Id = "https://es.wikiquote.org/wiki/William_Gladstone", Text = "Estoy convencido, por experiencia, de la inmensa ventaja de la estricta contabilidad en los primeros años de la vida. Es como aprender la gramática entonces, y que, una vez aprendida, no necesita ser referida después.", Author = "William Gladstone" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Thomas_de_Quincey", Text = "La memoria se fortalece con cada nueva carga que se echa sobre ella, y se vuelve tanto más fiel cuanto más confías en ella.", Author = "Thomas de Quincey" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Christian_Dior", Text = "La felicidad es el secreto de toda belleza. No hay belleza sin felicidad.", Author = "Christian Dior" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Luis_Cernuda", Text = "Abajo todo, todo, excepto la derrota.", Author = "Luis Cernuda" },
        new Quote { Id = "https://es.wikiquote.org/wiki/La_inc%C3%B3gnita", Text = "... el pobrecito está en la sepultura, y de allí no le han de sacar tus diligencias, ni las mías, ni las de nadie. Hoy le he mandado decir cuatro misas; créete, eso es lo que ha de valerle para la otra vida, y no las averiguaciones en ésta.", Author = "La incógnita" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carlos_Mart%C3%ADnez_Rivas", Text = "Hacer un poema es planear un crimen perfecto. Es urdir una mentira sin mácula hecha verdad a fuerza de pureza.", Author = "Carlos Martínez Rivas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Buey_%28refranes%29", Text = "Esperando que crezca la hierba, el buey se muere de hambre.[8] proverbios ingleses", Author = "Buey (refranes)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/%C3%81lvaro_Uribe_V%C3%A9lez", Text = "Pronunciamiento como candidato presidencial, 7 de mayo de 2002", Author = "Álvaro Uribe Vélez" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Arca_de_No%C3%A9", Text = "Comían, bebían, se casaban y se daban en casamiento, hasta el día en que entró Noé en el arca, y vino el diluvio y los destruyó a todos.", Author = "Arca de Noé" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alimento", Text = "Alimentar sin instruir, es el pecado de los padres.[2] proverbios chinos", Author = "Alimento" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Borracho", Text = "El hombre borracho puede hablar con los dioses.[12] proverbios chinos", Author = "Borracho" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Elena_Moncada", Text = "Para mí la prostitución no es un trabajo porque no se lo recomendarías a un hijo, hija, alguna amiga, gente querida. Esto no se lo recomendás a nadie, acá nos sos dueña de tu cuerpo, nunca podés elegir: siempre te elijen.", Author = "Elena Moncada" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pan", Text = "No hay pan pa' tanto chorizo.", Author = "Pan" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Burns", Text = "A mi edad, las flores me asustan.", Author = "George Burns" },
        new Quote { Id = "https://es.wikiquote.org/wiki/F%C3%A9lix_Pita_Rodr%C3%ADguez", Text = "Cierra la puerta, aguarda. Cierra la puerta, aguarda.", Author = "Félix Pita Rodríguez" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Franklin_Pierce_Adams", Text = "Hay muchos buenos cigarros de cinco centavos en el país. El problema es que cuestan un cuarto. Lo que este país realmente necesita es un buen níquel de cinco centavos.", Author = "Franklin Pierce Adams" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rodrigo_Bueno", Text = "A un ser humano se lo ayuda, se lo apoya, no se lo destruye ni se lo mata.", Author = "Rodrigo Bueno" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Logro%C3%B1o", Text = "Por Logroño pasa un río enorme llamado Ebro, de agua sana y rico en peces.", Author = "Logroño" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Frank_McCourt", Text = "Le diré a Mamá que has bebido una pinta en el ataud de Eugene.", Author = "Frank McCourt" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Marta_Vergara", Text = "Yo creía que la igualdad de derechos para las mujeres estaba por encima de la lucha de clases.", Author = "Marta Vergara" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Valdemoro", Text = "Y ya en el paso entre Valdemoro y Pinto, lugares famosos por sus alborozantes vinos, iba mi pensamiento tan recalentado en la mental contemplación de la sin par señora, que ya se me hacían siglos los minutos que tardara en rendirle toda mi voluntad...", Author = "Valdemoro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Nadie sabe para quién escribe. Cada libro es un mensaje lanzado en una botella al mar con la esperanza de que arribe a otra orilla.", Author = "Isabel Allende" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lu%C3%ADs_Espinal_Camps", Text = "Señor, tenemos la costumbre de acostumbrarnos a todo. Aun lo más hiriente se nos oxida. Quisiéramos una sensibilidad no cauterizada, para maravillarnos y sublevarnos. Señor, que no nos acostumbremos a ver injusticias, sin que se nos encienda la ira, y la actuación.", Author = "Luís Espinal Camps" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Amigo", Text = "Soy gran amigo y hago todo lo posible para que la gente me aprecie. Lo que más vale en la vida son los amigos. De eso estoy seguro y siempre lo he dicho. Desgraciadamente, por los caminos de la vida también se encuentra gente desleal.", Author = "Amigo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Diego_Simeone", Text = "El presupuesto se termina cuando pita el árbitro, y ahí entran el corazón, la ilusión... El corazón iguala el presupuesto.", Author = "Diego Simeone" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Max_Eastman", Text = "El peor enemigo de la esperanza humana no son los hechos brutos, sino los hombres con cerebro que no se enfrentan a ellos.", Author = "Max Eastman" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Kevin_Schwantz", Text = "Gané el premio Nº 1 aquí el año pasado y sentí que era justo para mí regresar e intentar defenderlo.", Author = "Kevin Schwantz" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alfredo_Casero", Text = "Esta mujer está acorralada,tiene odio clasista en la cabeza es una sociópata. Basta ya de enfermedad.", Author = "Alfredo Casero" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mar%C3%ADa_Eugenia_Vidal", Text = "Cuando uno está tan expuesto es inevitable que los que están al lado también. Y eso puede ser un desincentivo. Les pasa a mis hijos y a mis padres. Pero cuando el amor aparece de verdad todo eso es secundario.", Author = "María Eugenia Vidal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Arturo_Salcedo_Mart%C3%ADnez", Text = "Sin darse cuenta, Juan Ponce De León sembró la semilla prodigiosa que germinó la florida primavera que es el español que hablamos en Estados Unidos", Author = "Arturo Salcedo Martínez" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Dodie_Smith", Text = "Solo queda una página por escribir. Lo llenaré con palabras de una sola sílaba. Me encanta. Yo he amado. yo amaré.", Author = "Dodie Smith" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Paul_Bowles", Text = "Creo que un buen escritor debe estar loco. No realmente loco, lo que quiero decir es que debe ser diferente, original, no como el resto de la gente.", Author = "Paul Bowles" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Samuel_Edward_Konkin_III", Text = "En una sociedad agorista, la división del trabajo y el auto-respeto de cada trabajador-capitalista-emprendedor eliminará probablemente la tradicional organización empresarial —especialmente la jerarquía empresarial, una imitación del Estado y no del mercado—.", Author = "Samuel Edward Konkin III" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Desnudez", Text = "Quien está desnudo no deja caer nada.[25] proverbios japoneses", Author = "Desnudez" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Mar%C3%ADa_Morelos", Text = "Que la esclavitud se proscriba para siempre y lo mismo la distinción de castas. Quedando todos iguales, y sólo distinguirá a un americano de otro el vicio y la virtud.", Author = "José María Morelos" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Elvis_Presley", Text = "Cuando las cosas van mal, no vayas con ellas.", Author = "Elvis Presley" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lois_McMaster_Bujold", Text = "Solo en un aspecto se parecían los dos viajes: sentía que ambos eran un salto a lo desconocido.", Author = "Lois McMaster Bujold" },
        new Quote { Id = "https://es.wikiquote.org/wiki/%C3%81ngeles_Gonz%C3%A1lez-Sinde", Text = "¿Para qué necesitamos todos una línea de ADSL de no sé cuantos gigas? ¿Para mandar e-mails?.", Author = "Ángeles González-Sinde" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Eduardo_Zaplana", Text = "Me tengo que hacer rico porque estoy arruinado. Tengo que ganar mucho dinero, me hace falta mucho dinero para vivir...", Author = "Eduardo Zaplana" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Verbo", Text = "Al principio era el verbo, y el verbo estaba en Dios, y el verbo era Dios.", Author = "Verbo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rosal%C3%ADa_de_Castro", Text = "Alma que vas huyendo de ti misma,", Author = "Rosalía de Castro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ruth_Gavison", Text = "El sionismo no significa, y no debería significar, que solo a los judíos se les debería permitir vivir en el estado judío como ciudadanos iguales.", Author = "Ruth Gavison" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jerusal%C3%A9n%2C_la_emanaci%C3%B3n_del_gigante_Albi%C3%B3n", Text = "Debo crear un sistema o ser esclavizado por el de otro hombre. No razonaré ni compararé; mi empeño es crear.", Author = "Jerusalén, la emanación del gigante Albión" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pablo_Ignacio_Rossi", Text = "Aún en los centros más avanzados de progreso técnico y rendimiento educativo cohabitan y llegan a liderar los demagogos, los iluminados, los fundamentalistas o los tiranos potenciales.", Author = "Pablo Ignacio Rossi" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Richard_Feynman", Text = "Feynman [es] la combinación imposible de físico teórico y artista de circo, todo movimiento corporal y efectos de sonido.", Author = "Richard Feynman" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carlos_Salvador_Bilardo", Text = "El himno también es importante, nosotros lo practicábamos cinco veces antes de cada partido", Author = "Carlos Salvador Bilardo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Carlos_Mari%C3%A1tegui", Text = "No es posible democratizar la enseñanza de un país sin democratizar su economía y sin democratizar, por ende, su superestructura política.", Author = "José Carlos Mariátegui" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juglar", Text = "— Pues en verdad —respondió Sancho— que he oído yo decir a mi señor, que es zahorí de las historias, contando aquella de Lanzarote,cuando de Bretaña vino,que damas curaban dél,y dueñas del su rocino;y que en el particular de mi asno, que no le trocara yo con el rocín del señor Lanzarote.", Author = "Juglar" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Grandes_esperanzas", Text = "No hagas preguntas y no te contarán mentiras.", Author = "Grandes esperanzas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Diversidad", Text = "El andar en tierras y comunicar con diversas gentes, hace a los hombres discretos.", Author = "Diversidad" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tierra_%28materia%29", Text = "Pisando la tierra durade continuo el hombre está,y cada paso que daes sobre su sepultura.", Author = "Tierra (materia)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rafael_Bielsa", Text = "[...] la mayoría de los ciudadanos no existe como comunidad. Entonces todo se fragmenta, y con el tiempo se envilece el ejercicio democrático del poder", Author = "Rafael Bielsa" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Traducci%C3%B3n", Text = "Traductor, traidor.[9] proverbios italianos", Author = "Traducción" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Beas_de_Segura", Text = "En Beas, pon la capa donde la veas y aunque la veas no te lo creas.", Author = "Beas de Segura" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Richard_Stallman", Text = "Cuando me preguntan cuándo estará listo un programa, contesto: depende de cuánto trabajes en ello.", Author = "Richard Stallman" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alfredo_di_St%C3%A9fano", Text = "Lo bueno del fútbol es jugar al fútbol, porque si uno está en la cancha y no maniobra con la pelota, es correr al fútbol, no jugar al fútbol.", Author = "Alfredo di Stéfano" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Enrique_Lafuente_Ferrari", Text = "A cierta altura de la existencia es normal que el hombre comience a ser acuciado por el deseo de poner en claro el fundamento último de los impulsos y las tareas en que ha ido empleando el nada flojo quehacer de la vida.", Author = "Enrique Lafuente Ferrari" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Gertrude_Belle_Elion", Text = "Creo que quizás mi madre fue quien más me influenció. Ella era una ama de casa. No tuvo educación, pero tenía el sentido común mas grande que cualquier persona que yo conociera, y quería que yo tenga una carrera.", Author = "Gertrude Belle Elion" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rafael_del_Riego", Text = "... el 13 de noviembre de 1823, seis días después de ordenar la ejecución de Riego, Fernando VII, el Deseado, lanzó a la Nación todos los horrores de la saña política, de las venganzas personales, de la persecución contra el saber y el patriotismo.", Author = "Rafael del Riego" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_L%C3%B3pez_Portillo", Text = "Defenderé la paridad del peso como un perro", Author = "José López Portillo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vientre", Text = "La niebla de diciembre trae mar en el vientre.", Author = "Vientre" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Risa", Text = "Quítame el pan, si quieres, quítame el aire, pero no me quites tu risa.", Author = "Risa" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Teodoro_Garc%C3%ADa_Egea", Text = "Nunca había lanzado mas de 11 m. Ganar abrió una nueva etapa en mi vida.", Author = "Teodoro García Egea" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Serm%C3%B3n", Text = "El sermón de la montaña", Author = "Sermón" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Indulgencia", Text = "Cuando come la boca, el ojo se hace indulgente.[11] Proverbios árabes", Author = "Indulgencia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ratko_Mladi%C4%87", Text = "El comandante de las fuerzas armadas serbobosnias no viaja en burro.", Author = "Ratko Mladić" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Fortunata_y_Jacinta", Text = "La falta de educación es para el pobre una desventaja mayor que la pobreza.", Author = "Fortunata y Jacinta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/B._B._King", Text = "Y solo hay dos cosas que querría cambiar: terminar la escuela secundaria e ir a la universidad y tratar de aprender más sobre la música, ¡y no me casaría hasta después de los 40!.", Author = "B. B. King" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Harrison", Text = "Con cada error, seguramente debemos estar aprendiendo.", Author = "George Harrison" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Obra", Text = "Es feliz el que concilia su manera de obrar con la índole de las circunstancias.", Author = "Obra" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Humberto_Salvador", Text = "La naturaleza nos impone la suprema norma de la perpetua revolución estética.", Author = "Humberto Salvador" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Plan", Text = "Si haces planes para un año, siembra arroz. Si los haces para dos lustros, planta árboles. Si los haces para toda la vida, educa a una persona.[16] proverbios chinos", Author = "Plan" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Llanto", Text = "El llanto es una de las formas de la suprema dicha.", Author = "Llanto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sublime", Text = "Las cualidades sublimes infunden respeto; las bellas, amor.", Author = "Sublime" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Francisco_de_Goya", Text = "La casa es la sepultura de las mujeres.", Author = "Francisco de Goya" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lipograma", Text = "Un otoño —muchos años atrás—, cuando más olían las rosas y mayor sombra daban las acacias, un microbio muy conocido atacó, rudo y voraz, a Ramón Camomila: la furia matrimonial.", Author = "Lipograma" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Gaspar_N%C3%BA%C3%B1ez_de_Arce", Text = "Tú sólo puedes ser el soberanopoeta vengador, porque has reunidolas virtudes del pueblo castellano,y en tu grandioso canto enardecidosuena potente del león hispanoel formidable aterrador rugido.", Author = "Gaspar Núñez de Arce" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Federico_Andahazi", Text = "El azar traza a veces caminos imposibles.", Author = "Federico Andahazi" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Envidia", Text = "La envidia señala las virtudes del envidiado, y los defectos del envidioso.[21] proverbios árabes", Author = "Envidia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cipriano_de_Valera", Text = "En momentos de inestabilidad política o religiosa, Oxford ofreció su hospitalidad a eminentes estudiosos españoles como Cipriano de Valera, autor de la preciosa Biblia Castellana que, modernizada, todavía se sigue publicando.", Author = "Cipriano de Valera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Martillo", Text = "El yunque dura más que el martillo.[8] refranes estadounidenses", Author = "Martillo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Michael_Madsen", Text = "¿Vas a ladrar todo el día, perrito, o me vas a morder?.", Author = "Michael Madsen" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Douglas_Engelbart", Text = "La cantidad que una persona puede madurar es directamente proporcional a la vergüenza que puede pasar. Yo he pasado mucha vergüenza.", Author = "Douglas Engelbart" },
        new Quote { Id = "https://es.wikiquote.org/wiki/J._J._Thomson", Text = "¡Al electrón: quizás nunca sea utilidad para alguien!.", Author = "J. J. Thomson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jean_Sibelius", Text = "El marco de una sinfonía debe ser tan fuerte que te obligue a seguirlo, independientemente del entorno y las circunstancias: es una necesidad ética.", Author = "Jean Sibelius" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Julian_Casablancas", Text = "Tengo dos cosas: cerebro y pelotas. Y no prescindiría ninguna de las dos por nadie.", Author = "Julian Casablancas" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Marina_Abramovi%C4%87", Text = "Más que nada, tengo miedo de creer en mi propia grandeza.", Author = "Marina Abramović" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vilfredo_Pareto", Text = "El hombre es, en efecto, un ser poco racional y muy busca-razones. No se suele comportar de manera lógica, pero siempre tiene mucho interés en creérselo o hacer que los otros se lo crean.", Author = "Vilfredo Pareto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Arnold_Schwarzenegger", Text = "Mi madre quería que fuera a la escuela, pero seguí el consejo de mi padre. El ejercicio se convirtió en una obsesión, al punto de sentir que me enfermaría si me perdía un entrenamiento.", Author = "Arnold Schwarzenegger" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Santiago_Gamboa_Samper", Text = "Cómo es de rara la vida, no? De repente, sin andar uno buscando nada, algo se manifiesta. Fíjese lo de Osler… Si no vamos esa noche al cementerio yo no sabría que estaba muerto. ¿usté vio Flashdance, jefe?", Author = "Santiago Gamboa Samper" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Yalal_ad-Din_Muhammad_Rumi", Text = "El sonido del cañaveral no es el del viento, sino el del fuego, y sin fuego nada somos.", Author = "Yalal ad-Din Muhammad Rumi" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Frank_Shuman", Text = "Hemos demostrado la utilidad comercial de la energía del sol en los trópicos y en particular el resultado eficaz, nuestras tiendas de petróleo y carbón se agotan y la raza humana puede recibir el poder ilimitado de los rayos del Sol.", Author = "Frank Shuman" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cornelius_Castoriadis", Text = "Lo que llamo elucidación es el trabajo por el cual los hombres intentan pensar lo que hacen y saber lo que piensan.", Author = "Cornelius Castoriadis" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Gianni_Vernetti", Text = "La democracia no es solo convocar elecciones: es Estado de derecho, sistema de reglas, poderes separados, prensa autónoma, magistratura independiente.", Author = "Gianni Vernetti" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Epigrama", Text = "A la abeja semejante,para que cause placer,el epigrama ha de serpequeño, dulce y punzante.", Author = "Epigrama" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Talca", Text = "Talca, la soberbia, ha caído", Author = "Talca" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Luis_L%C3%B3pez_de_Mesa", Text = "El centro germinal de cualquier cultura consiste en el concepto que el hombre de esa cultura tenga de sí mismo.", Author = "Luis López de Mesa" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Werner_von_Siemens", Text = "Mi vida fue hermosa, porque fue esencialmente un esfuerzo fructífero y un trabajo útil.", Author = "Werner von Siemens" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Historia", Text = "La historia la escriben los vencedores.", Author = "Historia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Otto_Weininger", Text = "Lo masculino es positivo, productivo y moral, lo femenino es negativo, improductivo y amoral.", Author = "Otto Weininger" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Charles_Ives", Text = "La música es una de las formas que tiene Dios de golpear al hombre.", Author = "Charles Ives" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Manuel_de_la_Sota", Text = "Después de semejante enormidad, está claro que no hay problema que no se pueda superar ni dificultad que no se pueda vencer. Para lograrlo, en la vida, en la política y en la función pública, lo único que hay que hacer es distinguir lo importante. Lo importante de verdad.", Author = "José Manuel de la Sota" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jorge_VI", Text = "La más alta de las distinciones es el servicio a los demás.", Author = "Jorge VI" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alberto_Ascari", Text = "Siempre había sido mi norma, después de un accidente, conducir más rápido que nunca.", Author = "Alberto Ascari" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vigd%C3%ADs_Finnbogad%C3%B3ttir", Text = "Lo que ocurrió ese día estableció el primer paso para la emancipación de las mujeres en Islandia. Pralizó el país por completo y abrió los ojos de muchos hombres.", Author = "Vigdís Finnbogadóttir" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hugo_de_San_V%C3%ADctor", Text = "La sabiduría ilumina al hombre para que pueda reconocerse a sí mismo.", Author = "Hugo de San Víctor" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ian_Wilmut", Text = "Cualquier tipo de manipulación con embriones humanos debe ser prohibida.", Author = "Ian Wilmut" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jefferson_Davis", Text = "El principio por el cual luchamos está destinado a reafirmarse, aunque puede ser en otro momento y de otra forma.", Author = "Jefferson Davis" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carlos_Abascal", Text = "Dos hombrecitos no pueden reproducirse para formar una familia.", Author = "Carlos Abascal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Samuel_L._Jackson", Text = "Voté a Barack porque es negro. Es por esto por lo que unas personas votan a otras - porque se parecen a ellas... Esa es la política estadounidense, puro y simple.", Author = "Samuel L. Jackson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ana_Palacio", Text = "Las bolsas han subido y el petróleo ha bajado. Los ciudadanos ya pagan unos céntimos menos por la gasolina y el gasóleo. Eso son datos.", Author = "Ana Palacio" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sangre", Text = "Demasiado trabajo de pala es mejor que demasiado poco! Este trabajo ahorra sangre.", Author = "Sangre" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cinco", Text = "El rico tiene cinco sentidos y el pobre seis.[19] Proverbios suecos", Author = "Cinco" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Marshall_Meyer", Text = "Una sinagoga que sólo sirve para rezar, en realidad no sirve para nada y que si alguien quiere hacer del judaísmo un club privado, a mí no me interesa.", Author = "Marshall Meyer" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Josu_Jon_Imaz", Text = "Si lucho por tu libertad, si canto, no canto porque te quiero. Tampoco por enjugar tus lágrimas, sino porque te necesito felizmente libre. Porque en tu libertad, en tu felicidad, veo las mías.", Author = "Josu Jon Imaz" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lou_Holtz", Text = "La habilidad es lo que eres capaz de hacer. La motivación determina lo que haces. La actitud determina lo bien que lo haces.", Author = "Lou Holtz" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Dario_Fo", Text = "No hay mayor igualador que la estupidez de los hombres, especialmente cuando esos hombres tienen poder.", Author = "Dario Fo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Oveja", Text = "Un ejército de ovejas dirigido por un león es mucho más temible que un ejército de leones mandado por una oveja.", Author = "Oveja" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Metrodoro_de_L%C3%A1mpsaco_%28el_joven%29", Text = "Todos los bienes de los mortales son mortales.", Author = "Metrodoro de Lámpsaco (el joven)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Toni_Morrison", Text = "Me aburre mucho la gente que dice encontrar cosas poéticas en mis escritos. La buena prosa es poética. Mi noción de la poesía es que tiene que tener esa vida subterránea.", Author = "Toni Morrison" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Miriam_Germ%C3%A1n", Text = "Como madre de tres mujeres, abuela de varias mujeres, madre de alguien con capacidades diferenciadas, espero que a las mujeres no se nos vea como propiedad de nadie, sino otro ser capaz de crear un ambiente de libertad, de igualdad y de no quedarse en el camino.", Author = "Miriam Germán" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_en_espa%C3%B1ol_%28V%29", Text = "Va al hoyo el mozo y el gozo al pozo.", Author = "Refranes en español (V)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_en_espa%C3%B1ol_%28Y%29", Text = "Y dale Perico al torno.", Author = "Refranes en español (Y)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Antonio_Gala", Text = "El escritor, muchas veces, es como un caballo de carreras que ha perdido su jinete y ya no sabe por qué está corriendo ni dónde está la meta y, sin embargo, se le exige seguir corriendo aunque no sepa ni hacia dónde ni por qué razón", Author = "Antonio Gala" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Frank_Chodorov", Text = "Si suponemos que el individuo tiene un derecho indiscutible a la vida, debemos admitir que tiene un derecho similar al disfrute de los productos de su trabajo.", Author = "Frank Chodorov" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Luis_Herrero", Text = "En Cataluña las libertades están más amenazadas que en ninguna otra parte, lo que significa, la mayor amenaza a la libertad de expresión en tiempos democráticos.", Author = "Luis Herrero" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mariano_Azuela", Text = "La revolución beneficia al pobre, al ignorante, al que toda su vida ha sido esclavo, a los infelices que ni siquiera saben que si lo son es porque el rico convierte en oro las lágrimas, el sudor y la sangre de los pobres.", Author = "Mariano Azuela" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Modesto_Lomba", Text = "Yo apelaría aquí un poco a la responsabilidad que todos tenemos profesional en el contexto que nos une, que es este país.", Author = "Modesto Lomba" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sofia_Koval%C3%A9vskaya", Text = "Es imposible ser matemático sin ser un poeta del alma.", Author = "Sofia Kovalévskaya" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mar%C3%ADa_Dolores_de_Cospedal", Text = "[El Partido Popular] es el partido de los trabajadores.", Author = "María Dolores de Cospedal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Blanco_L%C3%B3pez", Text = "Uno no es ministro por méritos propios ni por curriculum académico, uno es ministro porque el presidente del Gobierno así lo decide. Hay miles y miles de ciudadanos que podrían hacerlo mejor que yo o tan bien como yo y que no tuvieron esa oportunidad.", Author = "José Blanco López" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bor%C3%ADs_Gryzlov", Text = "El Parlamento no es lugar para la discusión.", Author = "Borís Gryzlov" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Edward_Jenner", Text = "Espero que algún día la práctica de contagiar la viruela vacuna a los seres humanos se extienda por el mundo —cuando llegue ese día, ya no habrá más viruela—.", Author = "Edward Jenner" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Dominique_de_Villepin", Text = "Así que nadie puede afirmar en estos momentos que el camino de la guerra será más corto que el de las inspecciones. Como tampoco puede nadie afirmar que esa opción desembocaría en un mundo más seguro, más justo y estable. Y es que la guerra siempre es la prueba de un fracaso.", Author = "Dominique de Villepin" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lenny_Bruce", Text = "A la gente se le debe enseñar lo que es, no lo que debería ser. Todo mi humor está basado en la destrucción y la desesperación. Si el mundo entero estuviera tranquilo, sin enfermedad ni violencia, estaría en la línea del pan, justo detrás de J. Edgar Hoover.", Author = "Lenny Bruce" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ignorancia", Text = "Conocer nuestra ignorancia es la mejor parte del conocimiento.[5] proverbio chino", Author = "Ignorancia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Guns_N%27_Roses", Text = "Todo lo que necesitamos es un poco de paciencia - Patience, GN'R Lies", Author = "Guns N' Roses" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Karl_Weierstrass", Text = "Un matemático no es digno de ese nombre si no es un poco poeta.", Author = "Karl Weierstrass" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Andr%C3%A9i_Tarkovski", Text = "[El cine] abrió las posibilidades de recrear, de una forma nueva, la autentica atmósfera de la guerra, con su concentración hipertensa de nervios, invisible en la superficie pero haciéndose notar como un estruendo bajo la tierra.", Author = "Andréi Tarkovski" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Conciencia", Text = "La conciencia del ridículo suele ser más molesta que la conciencia del pecado.[5]>", Author = "Conciencia" },
        new Quote { Id = "https://es.wikiquote.org/wiki/As-Salih_Ismail_al-Malik", Text = "¡Mirad a este hombre injusto e ingrato que quiere quitarme mi país sin consideración para Dios ni para los hombres! Soy huérfano y cuento con vosotros para defenderme en memoria de mi padre que tanto os amó.", Author = "As-Salih Ismail al-Malik" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Patton", Text = "El soldado es el ejército. Ningún ejército es mejor que sus soldados. El soldado también es ciudadano. De hecho, la obligación y el privilegio más alto de la ciudadanía es el de portar armas para el país propio.", Author = "George Patton" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alfonso_Rojo", Text = "¿De qué sórdida pizzería has sacado a la invitada de hoy?", Author = "Alfonso Rojo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Robert_Fulghum", Text = "Creo que la imaginación es más fuerte que el conocimiento. Que el mito es más potente que la historia. Que los sueños son más poderosos que los hechos. Que la esperanza siempre triunfa sobre la experiencia. Que la risa es la única cura para la pena. Y que el amor es mas fuerte que la muerte.", Author = "Robert Fulghum" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Espuma", Text = "La palabra no es más que espuma que flota sobre el agua, y la acción, gota de oro que la agujerea.[9] proverbios tibetanos", Author = "Espuma" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Clara_Schumann", Text = "Sobre todo, me da la impresión de ser un niño mimado.", Author = "Clara Schumann" },
        new Quote { Id = "https://es.wikiquote.org/wiki/W._W._Rouse_Ball", Text = "Babbage fue uno de los fundadores de la Cambridge Analytical Society cuyo propósito, declaró, era abogar por los principios del d-ismo puro en oposición a la dof-edad de la universidad.", Author = "W. W. Rouse Ball" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mortal", Text = "Cada lágrima enseña a los mortales una verdad.", Author = "Mortal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Santiago_Vidaurri", Text = "Si lo creyeren conveniente, concurran a formar en un gobierno un todo compacto y respetable al extranjero, a la guerra contra los bárbaros y todo el que pretenda combatir los principios salvadores y de libertad.", Author = "Santiago Vidaurri" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jos%C3%A9_Lezama_Lima", Text = "Heidegger sostiene que el hombre es un ser para la muerte; todo poeta, sin embargo, crea la resurrección, entona ante la muerte un hurra victorioso. Y si alguno piensa que exagero, quedará preso de los desastres, del demonio y de los círculos infernales.", Author = "José Lezama Lima" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Baldomero_San%C3%ADn_Cano", Text = "Es menester estar convencido de lo que enseña para transmitirlo con probidad.", Author = "Baldomero Sanín Cano" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rafael_Azcona", Text = "Yo, como no soy rentista, creo que el dinero sirve para no pensar en el dinero.", Author = "Rafael Azcona" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Pata", Text = "Los pájaros se cazan por las patas. Los hombres, por las palabras.[10] proverbios indios", Author = "Pata" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Sancho_Panza", Text = "Allá va Sancho con su rocín.(Junceda:58)", Author = "Sancho Panza" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juan_Pablo_I", Text = "Como niño de pecho en brazos de su madre, así en mí está mi alma.", Author = "Juan Pablo I" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Techo", Text = "El techo del infierno está hecho de ocasiones perdidas.[11] refranes portugueses", Author = "Techo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Le%C3%B3n_Felipe", Text = "Felipe, León (2008). Nueva antología rota. Akal. ISBN 9788446027867.", Author = "León Felipe" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mon_Laferte", Text = "No lo hagan pa'la tele, haganlo de verdad", Author = "Mon Laferte" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juan_Pablo_Montoya", Text = "Aunque soy un conductor agresivo y lucho por el éxito, ciertamente no morderé a nadie, si es el ejemplo de Mike Tyson el que utilizamos....", Author = "Juan Pablo Montoya" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Celia_Cruz", Text = "Yo estaba en Miami en un restaurante cubano y cuando el camarero me preguntó si quería el café con azúcar o sin azúcar yo le dije: bueno ya sabes qué fuerte es el café de los cubanos así que: ¡Con azúcar chico! [5].", Author = "Celia Cruz" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rudolf_Hess", Text = "El Partido es Hitler!. Hitler es Alemania, asi como Alemania es Hitler!. Hitler! Sieg Heil! Sieg Heil!, Sieg Heil!.", Author = "Rudolf Hess" },
        new Quote { Id = "https://es.wikiquote.org/wiki/David_Beckham", Text = "El éxito no es sólo ganar, sino también disfrutar del juego.", Author = "David Beckham" },
        new Quote { Id = "https://es.wikiquote.org/wiki/J._M._Barrie", Text = "Cada vez que un chico dice yo no creo en las hadas hay un hada en algún lado que cae muerta.", Author = "J. M. Barrie" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Rafael_Sabatini", Text = "Debes cambiar al hombre, no a los sistemas.", Author = "Rafael Sabatini" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Neil_Armstrong", Text = "Un pequeño paso para el hombre, un salto gigantesco para la humanidad.", Author = "Neil Armstrong" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Christopher_Isherwood", Text = "Soy una cámara con su obturador abierto, totalmente pasivo, grabando, no pensando.", Author = "Christopher Isherwood" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Faustina_S%C3%A1ez_de_Melgar", Text = "Nada de análisis sociales, que disecan y empequeñecen el espíritu: nada de ofrecer a sus ojos los raquíticos cuadros realistas, que buscan con afán los innovadores en nuestra época transitoria.", Author = "Faustina Sáez de Melgar" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bernd_Schuster", Text = "Gracias, no hace falta decir nada más.", Author = "Bernd Schuster" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tesoro", Text = "La gente cree que es tesoro todo lo que vale mucho, pero el verdadero tesoro es lo que no se puede vender.", Author = "Tesoro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Consejo", Text = "Pídeles consejo a los viejos y los jóvenes, pero sigue tu propio sentido común.[4] proverbio árabe", Author = "Consejo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ra%C3%BAl_Alfons%C3%ADn", Text = "Hay que hacer la revolución primero de las expectativas y de las esperanzas en la Argentina.", Author = "Raúl Alfonsín" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Orilla", Text = "Cuando las olas se deslizan por la arena de la orilla, ¿podrías acaso separarlas?.[9] Proverbios malayos", Author = "Orilla" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Queso", Text = "A la bota dalla el beso después del queso. [6].", Author = "Queso" },
        new Quote { Id = "https://es.wikiquote.org/wiki/La_gata_sobre_el_tejado_de_zinc", Text = "¿En qué consiste la victoria de una gata sobre un tejado de hojalata caliente? Ojalá que lo supiera... Simplemente poder aguantar allí todo el tiempo que pueda, supongo.", Author = "La gata sobre el tejado de zinc" },
        new Quote { Id = "https://es.wikiquote.org/wiki/%C3%81ngel_Nieto", Text = "Yo soy un fan de Valentino, eso que nadie lo dude. A Valentino le debemos todos mucho. Ha hecho grande mundialmente el motociclismo... Si en algo se parece a mí es en que Valentino representa lo que yo intentaba ser.", Author = "Ángel Nieto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Espada", Text = "Las revoluciones empiezan por la palabra y concluyen por la espada.", Author = "Espada" },
        new Quote { Id = "https://es.wikiquote.org/wiki/F%C3%A9lix_Ovejero", Text = "La perversión del léxico político no es un vicio, es un procedimiento.", Author = "Félix Ovejero" },
        new Quote { Id = "https://es.wikiquote.org/wiki/%C3%8Dngrid_Betancourt", Text = "Se requiere un Congreso sin bandidos y una administración pública sin aves de rapiña.", Author = "Íngrid Betancourt" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Experimentaci%C3%B3n", Text = "Un cohete es un experimento; una estrella es una observación.", Author = "Experimentación" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Herbert", Text = "Dulce día, tan fresco, tan tranquilo, tan lucidor,Casamiento de la tierra y el cielo:El rocío llorará tu caída esta noche;Porque morirás.", Author = "George Herbert" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Cliente", Text = "Calidad es la adecuación para el uso satisfaciendo las necesidades del cliente.", Author = "Cliente" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mil", Text = "La conciencia vale por mil testigos.", Author = "Mil" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carl_Friedrich_Gauss", Text = "Debemos admitir con humildad que, mientras el número es puramente un producto de nuestra mente, el espacio tiene una realidad fuera de ella: por tanto, a priori no podemos describir completamente sus propiedades.", Author = "Carl Friedrich Gauss" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Dar%C3%ADo_Botero_Uribe", Text = "El estado no es nuestro objetivo, luchamos por cambiar la vida.", Author = "Darío Botero Uribe" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Matthew_Prior", Text = "Así, cansado de andar por ahí todo el día;/al anochecer, a ti, mi deleite, acudo.", Author = "Matthew Prior" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Riccardo_Muti", Text = "A pesar de ser una sociedad multiétnica, Estados Unidos debe trabajar con personas que provienen de culturas lejanas que tienen un valor universal y pueden convertirse en patrimonio de la humanidad.", Author = "Riccardo Muti" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ernesto_Gim%C3%A9nez_Caballero", Text = "Toda España huele hoy a Ateneo.", Author = "Ernesto Giménez Caballero" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Poncio_Pilato", Text = "¿No sabes que tengo autoridad para ponerte en libertad y tengo autoridad para fijarte en un madero?.", Author = "Poncio Pilato" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ernesto_P%C3%A9rez_Z%C3%BA%C3%B1iga", Text = "Creo que no hay otra obra con tal poder simbólico: no solo porque reúne la Edad Antigua y la Cristiana, que llega hasta nuestros días, sino porque ofrece alegorías que nos siguen importando. La Divina Comedia contiene posiblemente todos los símbolos de la experiencia y de la imaginación humana.", Author = "Ernesto Pérez Zúñiga" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Las_nieves_del_Kilimanjaro", Text = "Ahora estoy lleno de poesía. Podredumbre y poesía. Poesía podrida....", Author = "Las nieves del Kilimanjaro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Buenos_Aires", Text = "Mi Buenos Aires querido", Author = "Buenos Aires" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Atm%C3%B3sfera", Text = "Antes de que un secreto sea contado, a menudo se puede sentir el peso del mismo en la atmósfera.", Author = "Atmósfera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carlos_Humberto_Perette", Text = "Nuestro gobierno está dispuesto a convocar a todos los argentinos en esa tarea. Nadie puede renunciar a su deber. Con el esfuerzo común lograremos salvar a la República.", Author = "Carlos Humberto Perette" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Noviazgo", Text = "Las estrellasno tienen novio¡Tan bonitascomo son las estrellas!.", Author = "Noviazgo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Robo", Text = "Robar es provechoso, pero hacerse colgar resulta caro.[18] proverbios malayos", Author = "Robo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Verdadero_o_falso", Text = "La contradicción no es una señal de falsedad, ni la carencia de contradicción una señal de verdad.", Author = "Verdadero o falso" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Euskadi_Ta_Askatasuna", Text = "Todos tenemos que dar algo para que unos pocos no den todo", Author = "Euskadi Ta Askatasuna" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Jaime_Guzm%C3%A1n", Text = "La madre debe tener el hijo aunque salga anormal, no lo haya deseado, sea producto de una violación o aunque de tenerlo, derive su muerte", Author = "Jaime Guzmán" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Iskra_Lawrence", Text = "Sólo hay un tú en el mundo, así que deja de compararte con los demás y empieza a celebrar lo que te hace especial.", Author = "Iskra Lawrence" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Clooney", Text = "No me gusta compartir mi vida personal... no sería personal si la compartiera. [I don't like to share my personal life... it wouldn't be personal if I shared it].", Author = "George Clooney" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Le_Thanh_Tong", Text = "Cuando nos invade la pena, un día dura tanto como tres otoños.", Author = "Le Thanh Tong" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Obligaci%C3%B3n", Text = "El que juega por necesidad pierde por obligación.", Author = "Obligación" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Philip_Johnson", Text = "Las ciudades del siglo pasado no han competido entre sí por la belleza, sino por el humo, los vagones de carga y el crecimiento de la población. Fue incidental que incluso se construyeran monumentos únicos.", Author = "Philip Johnson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Robert_Stephenson", Text = "La manera de conseguir la felicidad es haciendo felices a los demás.", Author = "Robert Stephenson" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Lealtad", Text = "Leal saber y entender.", Author = "Lealtad" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juan_V%C3%A1zquez_de_Mella", Text = "El movimiento bolcheviquista tiene origen, impulso y dirección judaica", Author = "Juan Vázquez de Mella" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vital_Aza", Text = "Cuando la estafa es enorme ya toma un nombre decente.", Author = "Vital Aza" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Alberto_Lleras_Camargo", Text = "La guerra civil es el deporte nacional", Author = "Alberto Lleras Camargo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Helio_Pedregal", Text = "Fingimos que no sabemos para no comprometernos.", Author = "Helio Pedregal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bomba_at%C3%B3mica", Text = "Si los estados militarmente más poderosos -y menos amenazados- necesitan armas nucleares para su seguridad, ¿cómo puede uno negar esa seguridad a los países que están realmente inseguros. La política nuclear actual es una receta para la proliferación, es una política para el desastre.", Author = "Bomba atómica" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Eric_Berne", Text = "Cada persona diseña su propia vida, la libertad le da el poder para llevar a cabo sus propios designios, y el poder da la libertad de interferir en los designios de los demás.", Author = "Eric Berne" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Robert_Schuman", Text = "La libertad asusta cuando se ha perdido la costumbre de utilizarla.", Author = "Robert Schuman" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hugo_Moyano", Text = "La verdad, me siento más cómodo en un piquete o en un paro que acá.", Author = "Hugo Moyano" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Tabasco", Text = "Y vueltos a embarcar, navegamos costa a costa junto a tierra, hasta que llegamos a un río que llaman de Tabasco, que allí le pusimos nombre río de Grijalva.", Author = "Tabasco" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Antonio_Basagoiti", Text = "La acusación a Camps es una verdadera gilipollez y además la ha hecho un tipo que pasaba por allí, que dice que le ha llevado unos trajes, y que está condenado por otros delitos similares y no tiene ninguna credibilidad.", Author = "Antonio Basagoiti" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Andr%C3%A9s_Iniesta", Text = "El sentirte feliz como persona es superior a cualquier triunfo, es como lo veo.", Author = "Andrés Iniesta" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Marco_Polo", Text = "No he contado ni la mitad de lo que vi.", Author = "Marco Polo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/James_A._Michener", Text = "El carácter consiste en lo que haces en el tercer y cuarto intento.", Author = "James A. Michener" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Al_Smith", Text = "Cuando un hombre está fuera de la política, déjenlo que se quede afuera.", Author = "Al Smith" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Manuel_Rodr%C3%ADguez_Erdo%C3%ADza", Text = "Aún tenemos patria, ciudadanos.", Author = "Manuel Rodríguez Erdoíza" },
        new Quote { Id = "https://es.wikiquote.org/wiki/F%C3%A1cil_y_dif%C3%ADcil", Text = "No hay cosa, por fácil que sea, que no la haga difícil la mala gana.", Author = "Fácil y difícil" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ignacio_Zaragoza", Text = "Las armas nacionales se han cubierto de gloria. Las tropas francesas se portaron con valor en el combate y su jefe con torpeza.", Author = "Ignacio Zaragoza" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mafalda", Text = "Los otros días leí en el diario como funciona la caja de cambios del Ford Lotus y tampoco entendí un pito.", Author = "Mafalda" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bobby_Fischer", Text = "De eso se trata el ajedrez. Un día le das una lección a tu oponente, al día siguiente él te da una.", Author = "Bobby Fischer" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Anna_Hazare", Text = "La fuerza de la juventud en este movimiento es una señal de esperanza.", Author = "Anna Hazare" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Insulto", Text = "Ser viejo no es un insulto, es una consecuencia de la edad.", Author = "Insulto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Paco_Le%C3%B3n", Text = "Espero no ser una moda, quiero morirme actuando.", Author = "Paco León" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Mono", Text = "Cuando el mono ve que su culo está rojo, se niega a bailar. [19] proverbios egipcios", Author = "Mono" },
        new Quote { Id = "https://es.wikiquote.org/wiki/David_Held", Text = "La perpetua búsqueda de la seguridad parece solo haber engendrado una inseguridad crónica.", Author = "David Held" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Plauto", Text = "Seré rico si puedo guardar mi buen nombre.[23] o Si puedo preservar mi reputación, será suficiente riqueza.", Author = "Plauto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bernardo_Neustadt", Text = "Quiero comentarle a todos los argentinos: sepan que estamos ganando la guerra contra los ingleses", Author = "Bernardo Neustadt" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juliana_Di_Tullio", Text = "El Gobierno de Vidal no tiene perspectiva de género sino todo lo contrario.", Author = "Juliana Di Tullio" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Albert_Rivera", Text = "Aunque no me gustaría vivir en un país que diga que a partir de ahora es una configuración de naciones, para mí no es irrenunciable la modificación de la Constitución para contemplar la existencia de naciones en España.", Author = "Albert Rivera" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_en_espa%C3%B1ol_%28J%29", Text = "Jabón e hilo negro, todo es para la ropa.", Author = "Refranes en español (J)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Juan_Manuel_Roca", Text = "Fabrico espejos: Al horror le agrego más horror, más belleza a la belleza.", Author = "Juan Manuel Roca" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Refranes_en_espa%C3%B1ol_%28D%29", Text = "Da a los ricos lo suyo, a los pobres lo tuyo.", Author = "Refranes en español (D)" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Elie_Wiesel", Text = "Cada judío debería guardar, en algún lugar de su corazón, una zona para el odio, ese odio sano, varonil contra todo aquello que representa el alemán y que forma parte de la esencia de lo alemán. Todo lo demás sería traición a los muertos.", Author = "Elie Wiesel" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Vinton_Cerf", Text = "En el año 2005 los chips serán tan baratos que los encontraremos en todas partes: la nevera, la lavadora y cualquier otro electrodoméstico.", Author = "Vinton Cerf" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ary_Renan", Text = "Oigo los sollozos y su espiral inmensaestallar en tu seno, tu seno agonizante;escucho las aflicciones subir y descendera merced de los vendavales....", Author = "Ary Renan" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Arnaldo_Amalric", Text = "Fue en una abadía de la Orden de Cîteaux", Author = "Arnaldo Amalric" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Joaqu%C3%ADn_Leguina", Text = "Tienen que dedicarse a estudiar.", Author = "Joaquín Leguina" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hambre", Text = "Todos los hombres, mujeres y niños tienen derecho inalienable a no padecer hambre y desnutrición.", Author = "Hambre" },
        new Quote { Id = "https://es.wikiquote.org/wiki/1914", Text = "Todo iría mejorando. Ese era el mundo en el cual nací... De repente, sin que nadie lo esperara, cierta mañana de 1914, todo aquello terminó.", Author = "1914" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Gratitud", Text = "De desagradecidos está el infierno lleno.", Author = "Gratitud" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Arroyo", Text = "Vio en un arroyo estar lavando cantidad de mujeres, a quien preguntó si le sabrían decir si en aquel lugar vivía una mujer llamada Teresa Panza, mujer de un cierto Sancho Panza, escudero de un caballero llamado don Quijote de la Mancha.", Author = "Arroyo" },
        new Quote { Id = "https://es.wikiquote.org/wiki/George_Antheil", Text = "Aunque Antheil no sea exactamente el Shostakóvich americano, no vería ninguna ofensa en que los rusos comenzasen a llamar a Shostakóvich el Antheil ruso.", Author = "George Antheil" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Comenzar", Text = "Un viaje de mil millas comienza con el primer paso.", Author = "Comenzar" },
        new Quote { Id = "https://es.wikiquote.org/wiki/El_guardi%C3%A1n_entre_el_centeno", Text = "Si realmente te interesa saberlo, probablemente querrás saber primero dónde nací, y cómo fue mi puñetera niñez, y a qué se dedicaban mis padres y todo lo anterior a cuando me tuvieron a mí, y todo esa mierda tipo David Copperfield, pero no me apetece entrar en eso.", Author = "El guardián entre el centeno" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Garbi%C3%B1e_Biurrun", Text = "El derecho es el que tiene género, no sólo la justicia, porque está elaborado por hombres desde una óptica machista.", Author = "Garbiñe Biurrun" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Bien_y_mal", Text = "La vida ni es un bien ni un mal, es sólo ocasión de bien y de mal.Carta XCIX", Author = "Bien y mal" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Larry_Ellison", Text = "Construir Oracle para mí, fue como hacer un rompecabezas para niño.", Author = "Larry Ellison" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Guillermo_Tovar_de_Teresa", Text = "Los mexicanos sufrimos una enfermedad, una furia, un deseo de autodestruirnos, de cancelarnos, de borrarnos, de no dejar huella de nuestro pasado y de un modo de ser en el que creímos y al que nos consagramos.", Author = "Guillermo Tovar de Teresa" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Carlos_Pellicer_C%C3%A1mara", Text = "Las cosas por sí mismas manejan su propia retórica y su elocuencia es su patrimonio intrínseco.", Author = "Carlos Pellicer Cámara" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Indalecio_Prieto", Text = "A medida que la vida pasa por mí, yo, aunque internacionalista, me siento cada vez más español, siento a España dentro de mi corazón y la llevo hasta el tuétano de mis huesos.", Author = "Indalecio Prieto" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Julieta_Lanteri", Text = "Arden fogatas de emancipación femenina, venciendo rancios prejuicios y dejando de implorar sus derechos. Éstos no se mendigan, se conquistan.", Author = "Julieta Lanteri" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Francisco_Maturana", Text = "Perdimos pero ganamos un poco.", Author = "Francisco Maturana" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Ram%C3%B3n_P%C3%A9rez_de_Ayala", Text = "Gran ciencia es ser feliz, engendrar la alegría, porque sin ella toda existencia es baldía.", Author = "Ramón Pérez de Ayala" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Llanura", Text = "Recorrer la vida no es atravesar una llanura.[13] proverbios rusos", Author = "Llanura" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Parir", Text = "En el discurso de la cena preguntó don Juan a don Quijote qué nuevas tenía de la señora Dulcinea del Toboso: si se había casado, si estaba parida o preñada, o si, estando en su entereza, se acordaba —guardando su honestidad y buen decoro— de los amorosos pensamientos del señor don Quijote.", Author = "Parir" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Hermann_von_Helmholtz", Text = "La cantidad de fuerza que puede ponerse en práctica en la totalidad de la naturaleza es inmutable, y no puede ser aumentada ni disminuida.", Author = "Hermann von Helmholtz" },
        new Quote { Id = "https://es.wikiquote.org/wiki/William_Maxwell_Aitken", Text = "El deseo más vehemente de los norteamericanos es hacer dinero; el de los europeos, hacer política.", Author = "William Maxwell Aitken" },
        new Quote { Id = "https://es.wikiquote.org/wiki/John_Turturro", Text = "Alguien una vez nos preguntó sobre Turturro, si desarrollamos un código trabajando con él durante el curso de todas esas películas. Y contestamos: Está más allá de un código, ¡ni siquiera le hablamos!", Author = "John Turturro" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Robert_B._Parker", Text = "El arte de escribir un misterio es simplemente el arte de escribir ficción. Creas personajes interesantes, los pones en circunstancias interesantes y descubres cómo sacarlos de ellas. Normalmente nadie se sorprende del resultado de mis libros.", Author = "Robert B. Parker" },
        new Quote { Id = "https://es.wikiquote.org/wiki/Niebla", Text = "Un filósofo es un tipo que sube a una cumbre en busca del Sol; encuentra niebla, desciende y explica el magnífico espectáculo que ha visto.", Author = "Niebla" }
    };
}